    (2109101682588422145, '赣南脐橙 新鲜当季', '产地直发 坏果包赔', 2109101678394118155, 39.9, 50.7, 240, 1042, 'https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/382412e526034b4fb8d0727a7445c465.jpg', '["https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/382412e526034b4fb8d0727a7445c465.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/e9226a245a5248e09c1115b5319306ff.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/db7a822f89504fbdb223ca91e59ba619.jpg"]', '<p>【赣南脐橙 新鲜当季】产地直发 坏果包赔。产地直采，江西赣州发货，常温避光，保质期 30天。</p><p>采收后 24 小时内预冷分拣，全程冷链/保湿包装，坏果包赔；支持产地溯源批次查询。</p><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/e9226a245a5248e09c1115b5319306ff.jpg" style="width:100%;display:block" /><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/db7a822f89504fbdb223ca91e59ba619.jpg" style="width:100%;display:block" />', '江西赣州', DATE_SUB(CURDATE(), INTERVAL 8 DAY), '30天', '常温避光', 1, 90, 0),
    (2109101682588422146, '武鸣沃柑 薄皮蜜柑', '产地直发 现摘现发', 2109101678394118155, 25.9, 35.5, 500, 1298, 'https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/be4594c39f8d48a0aa8712d3f00132a3.jpg', '["https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/be4594c39f8d48a0aa8712d3f00132a3.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/f45ec9a56d174e7f97f84400dda9203c.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/d23e874538f64cd6be329796cf3fa530.jpg"]', '<p>【武鸣沃柑 薄皮蜜柑】产地直发 现摘现发。产地直采，广西南宁发货，常温避光，保质期 30天。</p><p>采收后 24 小时内预冷分拣，全程冷链/保湿包装，坏果包赔；支持产地溯源批次查询。</p><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/f45ec9a56d174e7f97f84400dda9203c.jpg" style="width:100%;display:block" /><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/d23e874538f64cd6be329796cf3fa530.jpg" style="width:100%;display:block" />', '广西南宁', DATE_SUB(CURDATE(), INTERVAL 9 DAY), '30天', '常温避光', 1, 80, 0),
    (2109101682588422147, '秭归夏橙 现摘直发', '产地直发 现摘现发', 2109101678394118155, 29.9, 37.4, 180, 368, 'https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/a940f3a0a4554441a0de90304c110364.jpg', '["https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/a940f3a0a4554441a0de90304c110364.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/8243a6ffa0bb4a0ca5ad6229c01ce805.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/54657ce05fd44f1184d175fdcfa28458.jpg"]', '<p>【秭归夏橙 现摘直发】产地直发 现摘现发。产地直采，湖北宜昌发货，常温避光，保质期 30天。</p><p>采收后 24 小时内预冷分拣，全程冷链/保湿包装，坏果包赔；支持产地溯源批次查询。</p><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/8243a6ffa0bb4a0ca5ad6229c01ce805.jpg" style="width:100%;display:block" /><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261025/54657ce05fd44f1184d175fdcfa28458.jpg" style="width:100%;display:block" />', '湖北宜昌', DATE_SUB(CURDATE(), INTERVAL 9 DAY), '30天', '常温避光', 1, 70, 0),
