INSERT INTO `review` (`id`, `order_id`, `product_id`, `user_id`, `rating`, `content`, `sentiment_label`, `sentiment_score`, `sentiment_keywords`, `is_anonymous`, `deleted`, `create_time`) VALUES
    (2109101695171334145, 0, 2109101682588422145, 2109101690977030145, 5, '赣南脐橙 新鲜当季太惊喜了，打开箱子就有果香，个头均匀没有坏果，家里老人孩子都爱吃', 1, 0.85, '新鲜,好吃,多汁,包装好', 1, 0, DATE_SUB(NOW(), INTERVAL 2 HOUR)),
    (2109101695171334146, 0, 2109101682588422145, 2109101690977030146, 5, '回购第三次了，赣南脐橙 新鲜当季品质一直很稳，产地直发就是新鲜，比超市买的强太多', 1, 0.86, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 9 HOUR)),
    (2109101695171334147, 0, 2109101682588422146, 2109101690977030146, 5, '包装很用心，每个都有独立格子防磕碰，武鸣沃柑 薄皮蜜柑到手完完整整，口感清甜多汁', 1, 0.86, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 5 HOUR)),
    (2109101695171334148, 0, 2109101682588422146, 2109101690977030147, 3, '一般般吧，武鸣沃柑 薄皮蜜柑个头比想象中小，味道中规中矩，不影响吃', 0, 0.55, '一般,还行', 0, 0, DATE_SUB(NOW(), INTERVAL 12 HOUR)),
    (2109101695171334149, 0, 2109101682588422146, 2109101690977030148, 5, '送人特有面子，产地溯源码扫一下就能看到采摘记录，武鸣沃柑 薄皮蜜柑吃着放心', 1, 0.9, '新鲜,好吃,多汁,包装好', 1, 0, DATE_SUB(NOW(), INTERVAL 19 HOUR)),
    (2109101695171334150, 0, 2109101682588422147, 2109101690977030147, 4, '秭归夏橙 现摘直发整体不错，个头稍小的有几个，但味道在线，性价比可以', 1, 0.88, '不错,新鲜,实惠', 0, 0, DATE_SUB(NOW(), INTERVAL 8 HOUR)),
    (2109101695171334151, 0, 2109101682588422147, 2109101690977030148, 5, '客服态度好物流也快，秭归夏橙 现摘直发比图片还好看，甜度刚刚好不齁，五星好评', 1, 0.9, '新鲜,好吃,多汁,包装好', 1, 0, DATE_SUB(NOW(), INTERVAL 15 HOUR)),
    (2109101695171334152, 0, 2109101682588422147, 2109101690977030149, 2, '秭归夏橙 现摘直发到手有点蔫了，新鲜度不太够，和描述有差距，希望改进运输包装', -1, 0.27, '不新鲜,有磕碰', 0, 0, DATE_SUB(NOW(), INTERVAL 22 HOUR)),
    (2109101695171334153, 0, 2109101682588422147, 2109101690977030150, 4, '秭归夏橙 现摘直发味道不错，分量实在，下次搞活动再囤一点', 1, 0.92, '不错,新鲜,实惠', 0, 0, DATE_SUB(NOW(), INTERVAL 29 HOUR)),
    (2109101695171334154, 0, 2109101682588422148, 2109101690977030148, 4, '比预期好，福建琯溪蜜柚 三红肉果肉饱满，就是发货慢了半天，总体满意', 1, 0.9, '不错,新鲜,实惠', 1, 0, DATE_SUB(NOW(), INTERVAL 11 HOUR)),
    (2109101695171334155, 0, 2109101682588422148, 2109101690977030149, 5, '回购第三次了，福建琯溪蜜柚 三红肉品质一直很稳，产地直发就是新鲜，比超市买的强太多', 1, 0.91, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 18 HOUR)),
    (2109101695171334156, 0, 2109101682588422149, 2109101690977030149, 5, '包装很用心，每个都有独立格子防磕碰，象山红美人 柑橘到手完完整整，口感清甜多汁', 1, 0.91, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 14 HOUR)),
    (2109101695171334157, 0, 2109101682588422149, 2109101690977030150, 5, '象山红美人 柑橘新鲜度满分，看得出来是刚采摘就发的，果肉紧实味道正，值得推荐', 1, 0.92, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 21 HOUR)),
    (2109101695171334158, 0, 2109101682588422149, 2109101690977030151, 4, '比预期好，象山红美人 柑橘果肉饱满，就是发货慢了半天，总体满意', 1, 0.94, '不错,新鲜,实惠', 1, 0, DATE_SUB(NOW(), INTERVAL 28 HOUR)),
    (2109101695171334159, 0, 2109101682588422150, 2109101690977030150, 5, '送人特有面子，产地溯源码扫一下就能看到采摘记录，丹东红颜草莓吃着放心', 1, 0.92, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 17 HOUR)),
    (2109101695171334160, 0, 2109101682588422150, 2109101690977030151, 3, '一般般吧，丹东红颜草莓个头比想象中小，味道中规中矩，不影响吃', 0, 0.55, '一般,还行', 1, 0, DATE_SUB(NOW(), INTERVAL 24 HOUR)),
    (2109101695171334161, 0, 2109101682588422150, 2109101690977030152, 5, '丹东红颜草莓太惊喜了，打开箱子就有果香，个头均匀没有坏果，家里老人孩子都爱吃', 1, 0.95, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 31 HOUR)),
    (2109101695171334162, 0, 2109101682588422150, 2109101690977030145, 4, '新鲜度可以，包装到位，丹东红颜草莓有一点酸尾，配着吃正好', 1, 0.97, '不错,新鲜,实惠', 0, 0, DATE_SUB(NOW(), INTERVAL 38 HOUR)),
    (2109101695171334163, 0, 2109101682588422151, 2109101690977030151, 4, '云南高山蓝莓整体不错，个头稍小的有几个，但味道在线，性价比可以', 1, 0.94, '不错,新鲜,实惠', 1, 0, DATE_SUB(NOW(), INTERVAL 20 HOUR)),
    (2109101695171334164, 0, 2109101682588422151, 2109101690977030152, 5, '回购第三次了，云南高山蓝莓品质一直很稳，产地直发就是新鲜，比超市买的强太多', 1, 0.95, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 27 HOUR)),
    (2109101695171334165, 0, 2109101682588422152, 2109101690977030152, 4, '比预期好，烟台大樱桃 美早果肉饱满，就是发货慢了半天，总体满意', 1, 0.95, '不错,新鲜,实惠', 0, 0, DATE_SUB(NOW(), INTERVAL 23 HOUR)),
    (2109101695171334166, 0, 2109101682588422152, 2109101690977030145, 5, '烟台大樱桃 美早新鲜度满分，看得出来是刚采摘就发的，果肉紧实味道正，值得推荐', 1, 0.97, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 30 HOUR)),
