    (2109101695171334742, 0, 2109101682588422344, 2109101690977030145, 5, '黄精 九蒸九晒新鲜度满分，看得出来是刚采摘就发的，果肉紧实味道正，值得推荐', 1, 0.85, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 606 HOUR)),
    (2109101695171334743, 0, 2109101682588422344, 2109101690977030146, 1, '黄精 九蒸九晒有三个坏果，联系客服补发了但体验不好，谨慎下单', -1, 0.18, '坏果,失望', 1, 0, DATE_SUB(NOW(), INTERVAL 613 HOUR)),
    (2109101695171334744, 0, 2109101682588422345, 2109101690977030145, 5, '送人特有面子，产地溯源码扫一下就能看到采摘记录，长白山人参片吃着放心', 1, 0.85, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 602 HOUR)),
    (2109101695171334745, 0, 2109101682588422345, 2109101690977030146, 5, '客服态度好物流也快，长白山人参片比图片还好看，甜度刚刚好不齁，五星好评', 1, 0.86, '新鲜,好吃,多汁,包装好', 1, 0, DATE_SUB(NOW(), INTERVAL 609 HOUR)),
    (2109101695171334746, 0, 2109101682588422345, 2109101690977030147, 4, '比预期好，长白山人参片果肉饱满，就是发货慢了半天，总体满意', 1, 0.88, '不错,新鲜,实惠', 0, 0, DATE_SUB(NOW(), INTERVAL 616 HOUR)),
    (2109101695171334747, 0, 2109101682588422345, 2109101690977030148, 5, '回购第三次了，长白山人参片品质一直很稳，产地直发就是新鲜，比超市买的强太多', 1, 0.9, '新鲜,好吃,多汁,包装好', 0, 0, DATE_SUB(NOW(), INTERVAL 623 HOUR)),
    (2109101695171334748, 0, 2109101682588422346, 2109101690977030146, 5, '糯米酒 月子酒太惊喜了，打开箱子就有果香，个头均匀没有坏果，家里老人孩子都爱吃', 1, 0.86, '新鲜,好吃,多汁,包装好', 1, 0, DATE_SUB(NOW(), INTERVAL 605 HOUR)),
    (2109101695171334749, 0, 2109101682588422346, 2109101690977030147, 3, '一般般吧，糯米酒 月子酒个头比想象中小，味道中规中矩，不影响吃', 0, 0.55, '一般,还行', 0, 0, DATE_SUB(NOW(), INTERVAL 612 HOUR));
